async function syncStripeFees(db3, managerId, limit = 100) {
  const Stripe9 = (await import("stripe")).default;
  const stripeSecretKey7 = process.env.STRIPE_SECRET_KEY;
  if (!stripeSecretKey7) {
    throw new Error("STRIPE_SECRET_KEY not configured");
  }
  const stripe7 = new Stripe9(stripeSecretKey7, {
    apiVersion: "2026-02-25.clover"
  });
  const whereConditions = [
    sql11`payment_intent_id IS NOT NULL`,
    sql11`(stripe_processing_fee IS NULL OR stripe_processing_fee = '0')`,
    sql11`status IN ('succeeded', 'partially_refunded')`
  ];
  if (managerId) {
    whereConditions.push(sql11`manager_id = ${managerId}`);
  }
  const whereClause = sql11`WHERE ${sql11.join(whereConditions, sql11` AND `)}`;
  const result = await db3.execute(sql11`
    SELECT id, payment_intent_id, amount, manager_id
    FROM payment_transactions
    ${whereClause}
    ORDER BY created_at DESC
    LIMIT ${limit}
  `);
  let synced = 0;
  let failed = 0;
  const errors = [];
  for (const row of result.rows) {
    const transactionId = row.id;
    const paymentIntentId = row.payment_intent_id;
    try {
      const paymentIntent = await stripe7.paymentIntents.retrieve(paymentIntentId, {
        expand: ["latest_charge"]
      });
      if (!paymentIntent.latest_charge) {
        errors.push(`Transaction ${transactionId}: No charge found for PaymentIntent ${paymentIntentId}`);
        failed++;
        continue;
      }
      const charge = typeof paymentIntent.latest_charge === "string" ? await stripe7.charges.retrieve(paymentIntent.latest_charge) : paymentIntent.latest_charge;
      if (!charge.balance_transaction) {
        errors.push(`Transaction ${transactionId}: No balance_transaction for charge ${charge.id}`);
        failed++;
        continue;
      }
      const balanceTransactionId = typeof charge.balance_transaction === "string" ? charge.balance_transaction : charge.balance_transaction.id;
      const balanceTransaction = await stripe7.balanceTransactions.retrieve(balanceTransactionId);
      const stripeProcessingFee = balanceTransaction.fee;
      const stripeAmount = paymentIntent.amount;
      const stripePlatformFee = paymentIntent.application_fee_amount || 0;
      const stripeNetAmount = stripePlatformFee > 0 ? stripeAmount - stripePlatformFee : stripeAmount - stripeProcessingFee;
      await updatePaymentTransaction(
        transactionId,
        {
          stripeAmount,
          stripeNetAmount,
          stripeProcessingFee,
          stripePlatformFee,
          lastSyncedAt: /* @__PURE__ */ new Date()
        },
        db3
      );
      logger.info(`[Stripe Sync] \u2705 Synced transaction ${transactionId}: fee=${stripeProcessingFee} cents`);
      synced++;
      await new Promise((resolve) => setTimeout(resolve, 100));
    } catch (error) {
      errors.push(`Transaction ${transactionId}: ${error.message}`);
      failed++;
    }
  }
  return { synced, failed, errors };
}
